context_title:
Ezt ird at ugy hpgy olyan designje legyen mint a csatolt html fàjlnak
Teljes kódot kijavítva vissza küldöd. minden egyes karaktert leírsz, nem rövidítesz. minden hibát kijavítasz. egy fájl marad. ne írj semmi mást csak a teljes kódot es kommentek nem lehetnek benne! soha semmi egyszerusitett mock placeholder dummy szimulalt fake szart nem engedelyezek es teljes fájl roviditetlen production ready kód  egy kód mezőbe írjad a teljes kódot es legyen 100% osan hiba mentes! 

import { useMemo, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { ChevronRight, FileCode2, GitBranch, History, Loader2, MessageSquare, PanelLeft, Play, Plus, Save, Send, ShieldCheck, Sparkles, TerminalSquare } from 'lucide-react';
import { useGetWorkspaceTree, useGetWorkspaceFile, useWriteWorkspaceFile, useRunWorkspaceCommand, useListCheckpoints, useCreateCheckpoint, useGetAgentStatus, getGetWorkspaceFileQueryKey, getGetWorkspaceTreeQueryKey, getListCheckpointsQueryKey } from '@workspace/api-client-react';
import type { ChatMessage } from '@workspace/api-client-react';
import { cn } from '@/lib/utils';
import { CodeEditor, EmptyState, ErrorBlock, FileTree, LoadingBlock, SectionTitle, StatusBadge } from '@/components/studio-primitives';

type Mode = 'plan' | 'build' | 'debug';

const starterMessages: ChatMessage[] = [
  { role: 'assistant', content: 'Workspace linked. Tell me what to build, fix, or investigate. I will keep the plan and every file change visible here.' },
];

export default function Workspace() {
  const queryClient = useQueryClient();
  const [selectedPath, setSelectedPath] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>(starterMessages);
  const [prompt, setPrompt] = useState('');
  const [mode, setMode] = useState<Mode>('build');
  const [command, setCommand] = useState('pnpm test');
  const [commandResult, setCommandResult] = useState<{ stdout: string; stderr: string; exitCode: number; durationMs: number; command: string } | null>(null);
  const [checkpointLabel, setCheckpointLabel] = useState('');
  const [showTerminal, setShowTerminal] = useState(true);
  const [showTree, setShowTree] = useState(true);
  const [draft, setDraft] = useState<{ path: string; value: string } | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);

  const tree = useGetWorkspaceTree();
  const file = useGetWorkspaceFile({ path: selectedPath || 'README.md' }, { query: { enabled: Boolean(selectedPath), queryKey: getGetWorkspaceFileQueryKey({ path: selectedPath || 'README.md' }) } });
  const status = useGetAgentStatus();
  const checkpoints = useListCheckpoints();
  const writeFile = useWriteWorkspaceFile();
  const runCommand = useRunWorkspaceCommand();
  const createCheckpoint = useCreateCheckpoint();

  const entries = tree.data?.entries || [];
  const activeFile = file.data;
  const checkpointCount = checkpoints.data?.length || 0;
  const modelName = status.data?.model || 'Model offline';
  const workspaceStats = useMemo(() => {
    const files = entries.filter((entry) => entry.kind === 'file');
    return { files: files.length, bytes: files.reduce((sum, entry) => sum + entry.size, 0) };
  }, [entries]);

  const sendMessage = async () => {
    const message = prompt.trim();
    if (!message || isStreaming) return;
    const next = [...messages, { role: 'user' as const, content: message }, { role: 'assistant' as const, content: 'Working through the request' }];
    setMessages(next);
    setPrompt('');
    setIsStreaming(true);
    try {
      const response = await fetch('/api/agent/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message, history: next.slice(0, -1), mode, context: selectedPath || null }),
      });
      if (!response.ok || !response.body) throw new Error('The agent endpoint did not return a stream.');
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      while (true) {
        const { value, done } = await reader.read();
        buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';
        for (const line of lines) {
          if (!line.startsWith('data: ')) continue;
          const event = JSON.parse(line.slice(6)) as { type: string; content?: string; message?: string; tool?: string; path?: string; detail?: string; label?: string };
          if (event.type === 'message') {
            setMessages((current) => current.map((item, index) => index === current.length - 1 ? { ...item, content: event.content || '' } : item));
          } else if (event.type === 'activity') {
            setMessages((current) => current.map((item, index) => index === current.length - 1 ? { ...item, content: `${event.detail || event.label || 'Agent activity'}\n\n${item.content}` } : item));
          } else if (event.type === 'tool') {
            const detail = event.path ? `${event.tool}: ${event.path}` : `${event.tool || 'tool'} completed`;
            setMessages((current) => current.map((item, index) => index === current.length - 1 ? { ...item, content: `${detail}\n\n${item.content}` } : item));
          } else if (event.type === 'error') {
            setMessages((current) => current.map((item, index) => index === current.length - 1 ? { ...item, content: event.message || 'The agent returned an error.' } : item));
          }
        }
        if (done) break;
      }
    } catch (error) {
      setMessages((current) => current.map((item, index) => index === current.length - 1 ? { ...item, content: error instanceof Error ? error.message : 'Could not reach the agent endpoint.' } : item));
    } finally {
      setIsStreaming(false);
      queryClient.invalidateQueries({ queryKey: getGetWorkspaceTreeQueryKey() });
      queryClient.invalidateQueries({ queryKey: getListCheckpointsQueryKey() });
    }
  };

  const saveFile = () => {
    if (!selectedPath) return;
    writeFile.mutate({ data: { path: selectedPath, content: draft?.path === selectedPath ? draft.value : activeFile?.content || '' } }, {
      onSuccess: (saved) => {
        setDraft({ path: selectedPath, value: saved.content });
        queryClient.setQueryData(getGetWorkspaceFileQueryKey({ path: selectedPath }), saved);
        queryClient.invalidateQueries({ queryKey: getGetWorkspaceTreeQueryKey() });
      },
    });
  };

  const run = () => {
    const value = command.trim();
    if (!value || runCommand.isPending) return;
    runCommand.mutate({ data: { command: value, cwd: tree.data?.root || '', timeoutMs: 120000 } }, { onSuccess: setCommandResult });
  };

  const create = () => {
    const label = checkpointLabel.trim();
    if (!label || createCheckpoint.isPending) return;
    createCheckpoint.mutate({ data: { label } }, {
      onSuccess: () => {
        setCheckpointLabel('');
        queryClient.invalidateQueries({ queryKey: getListCheckpointsQueryKey() });
      },
    });
  };

  return (
    <div className="grid min-h-[calc(100dvh-54px)] grid-cols-1 xl:grid-cols-[minmax(380px,1.12fr)_minmax(450px,1.4fr)]">
      <section className="relative flex min-h-[700px] flex-col border-b border-border/75 xl:border-b-0 xl:border-r">
        <div className="flex items-center justify-between border-b border-border/75 px-4 py-3.5 lg:px-6">
          <div className="flex items-center gap-3">
            <div className="grid h-7 w-7 place-items-center rounded-md bg-primary/12 text-primary"><Sparkles size={14} /></div>
            <div><h1 className="text-sm font-bold tracking-tight">Direct the workspace</h1><p className="font-mono text-[9px] uppercase tracking-wider text-muted-foreground">conversation / {mode}</p></div>
          </div>
          <StatusBadge tone={status.data?.configured ? 'green' : 'amber'}>{status.data?.configured ? 'agent online' : 'configure agent'}</StatusBadge>
        </div>
        <div className="grid-bg relative flex-1 overflow-y-auto px-4 py-5 lg:px-6">
          <div className="mx-auto max-w-[640px] space-y-5">
            <div className="flex items-center gap-3 text-[10px] text-muted-foreground"><span className="h-px flex-1 bg-border/70" /><span className="font-mono uppercase tracking-[.16em]">session started</span><span className="h-px flex-1 bg-border/70" /></div>
            {messages.map((message, index) => <MessageBubble key={`${message.role}-${index}`} message={message} index={index} />)}
            {isStreaming && <div className="animate-rise flex gap-3"><div className="mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-md border border-primary/25 bg-primary/10 text-primary"><Sparkles size={13} /></div><div className="rounded-lg border border-border bg-card px-4 py-3"><div className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary" /><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary [animation-delay:120ms]" /><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary [animation-delay:240ms]" /> thinking through the change</div></div></div>}
          </div>
        </div>
        <div className="border-t border-border/75 bg-card/55 p-4 lg:p-5">
          <div className="mx-auto max-w-[640px]">
            <div className="mb-2 flex items-center gap-1.5">
              {(['plan', 'build', 'debug'] as Mode[]).map((value) => <button key={value} data-testid={`button-mode-${value}`} onClick={() => setMode(value)} className={cn('rounded-md px-2.5 py-1 font-mono text-[9px] uppercase tracking-wider transition-colors', mode === value ? 'bg-primary/15 text-primary' : 'text-muted-foreground hover:bg-secondary hover:text-foreground')}>{value}</button>)}
              <span className="ml-auto font-mono text-[9px] text-muted-foreground">{modelName}</span>
            </div>
            <div className="rounded-xl border border-border bg-background shadow-[0_8px_30px_hsl(220_24%_5%/.18)] focus-within:border-primary/60 focus-within:ring-1 focus-within:ring-primary/30">
              <textarea data-testid="input-agent-prompt" value={prompt} onChange={(event) => setPrompt(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) void sendMessage(); }} placeholder="Ask the agent to make a change" rows={3} className="w-full resize-none bg-transparent px-4 py-3 text-sm outline-none placeholder:text-muted-foreground/65" />
              <div className="flex items-center justify-between border-t border-border/70 px-3 py-2">
                <div className="flex items-center gap-2 text-[10px] text-muted-foreground"><span className="font-mono">⌘↵</span> to send <span className="hidden text-border sm:inline">·</span><span className="hidden sm:inline">Context: {selectedPath || 'workspace'}</span></div>
                <button data-testid="button-send-agent" onClick={() => void sendMessage()} disabled={!prompt.trim() || isStreaming} className="grid h-7 w-7 place-items-center rounded-md bg-primary text-primary-foreground transition-transform hover:scale-105 disabled:cursor-not-allowed disabled:opacity-40"><Send size={14} /></button>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="flex min-h-[700px] min-w-0 flex-col bg-[#0e1317]">
        <div className="flex items-center justify-between border-b border-[#242c32] bg-[#12181d] px-3 py-2">
          <div className="flex items-center gap-1">
            <button data-testid="button-toggle-tree" onClick={() => setShowTree((value) => !value)} className={cn('grid h-7 w-7 place-items-center rounded text-[#8d9aa3] hover:bg-[#20282f] hover:text-[#d6e0e5]', showTree && 'bg-[#20282f] text-[#e0ad4e]')}><PanelLeft size={14} /></button>
            <span className="mx-2 h-4 w-px bg-[#2a333a]" />
            <GitBranch size={13} className="text-[#72c9a6]" /><span className="font-mono text-[10px] text-[#9ba7ae]">main</span>
          </div>
          <div className="flex items-center gap-2 font-mono text-[9px] text-[#65727b]"><span>{workspaceStats.files} files</span><span>·</span><span>{formatBytes(workspaceStats.bytes)}</span></div>
        </div>
        <div className="flex min-h-0 flex-1">
          {showTree && <div className="w-[180px] shrink-0 border-r border-[#242c32] bg-[#10161b] sm:w-[215px]"><SectionTitle icon={<FolderTreeIcon />} title="Files" count={String(entries.length)} /><div className="max-h-[400px] overflow-y-auto">{tree.isLoading ? <LoadingBlock lines={5} /> : tree.isError ? <ErrorBlock onRetry={() => tree.refetch()} /> : <FileTree entries={entries} selected={selectedPath} onSelect={(path) => { setSelectedPath(path); setDraft(null); }} />}</div><div className="border-t border-[#242c32] p-3"><div className="mb-2 flex items-center gap-2 text-[9px] uppercase tracking-wider text-[#697680]"><ShieldCheck size={12} className="text-[#72c9a6]" /> checkpoints</div>{checkpoints.isLoading ? <div className="h-3 w-2/3 animate-pulse rounded bg-[#20282f]" /> : <div className="font-mono text-[10px] text-[#a6b2b8]">{checkpointCount} saved snapshots</div>}</div></div>}
          <div className="flex min-w-0 flex-1 flex-col">
            <div className="flex h-10 items-center gap-2 border-b border-[#242c32] bg-[#141b20] px-3">
              <FileCode2 size={14} className="text-[#e0ad4e]" /><span className="min-w-0 truncate font-mono text-[11px] text-[#d6e0e5]">{selectedPath || 'Select a file to inspect'}</span>
              {selectedPath && <button data-testid="button-save-file" onClick={saveFile} className="ml-auto flex items-center gap-1.5 rounded px-2 py-1 font-mono text-[9px] text-[#aebbc1] hover:bg-[#242c32] hover:text-[#e0ad4e]"><Save size={12} /> save</button>}
            </div>
            {selectedPath ? (file.isLoading ? <LoadingBlock lines={12} /> : file.isError ? <ErrorBlock onRetry={() => file.refetch()} /> : <CodeEditor value={draft?.path === selectedPath ? draft.value : activeFile?.content || ''} onChange={(value) => setDraft({ path: selectedPath, value })} language={activeFile?.language} onSave={saveFile} saving={writeFile.isPending} />) : <EmptyState icon={<FileCode2 size={26} />} title="Inspect before you change" body="Select a file from the tree to open its contents here. Keyboard shortcut: ⌘S saves the active file." />}
            <div className="border-t border-[#242c32]">
              <div className="flex items-center justify-between border-b border-[#242c32] bg-[#12181d] px-3 py-2"><div className="flex items-center gap-2"><TerminalSquare size={13} className="text-[#72c9a6]" /><span className="font-mono text-[10px] uppercase tracking-wider text-[#aebbc1]">Terminal</span>{commandResult && <span className={cn('font-mono text-[9px]', commandResult.exitCode === 0 ? 'text-[#72c9a6]' : 'text-[#e27b6e]')}>{commandResult.exitCode === 0 ? 'completed' : 'failed'}</span>}</div><button data-testid="button-toggle-terminal" onClick={() => setShowTerminal((value) => !value)} className="text-[#71808a] hover:text-[#d6e0e5]">{showTerminal ? <ChevronRight size={14} className="rotate-90" /> : <ChevronRight size={14} />}</button></div>
              {showTerminal && <div className="bg-[#0b1013] p-3"><div className="flex items-center gap-2"><span className="font-mono text-[11px] text-[#72c9a6]">$</span><input data-testid="input-terminal-command" value={command} onChange={(event) => setCommand(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') run(); }} className="min-w-0 flex-1 bg-transparent font-mono text-[11px] text-[#d6e0e5] outline-none" /><button data-testid="button-run-command" onClick={run} disabled={runCommand.isPending} className="flex items-center gap-1.5 rounded bg-[#20362f] px-2 py-1 font-mono text-[9px] uppercase tracking-wider text-[#72c9a6] hover:bg-[#2a463b] disabled:opacity-45">{runCommand.isPending ? <Loader2 size={11} className="animate-spin" /> : <Play size={11} />} run</button></div>{commandResult && <pre data-testid="text-terminal-output" className="mt-3 max-h-28 overflow-auto whitespace-pre-wrap border-t border-[#1d272d] pt-3 font-mono text-[10px] leading-relaxed text-[#9ba7ae]">{commandResult.stdout || commandResult.stderr || `Command exited with code ${commandResult.exitCode}`}<span className="mt-2 block text-[#59666e]">completed in {commandResult.durationMs}ms</span></pre>}</div>}
            </div>
          </div>
        </div>
      </section>
      <div className="fixed bottom-[62px] right-5 z-10 hidden xl:block">
        <div className="flex items-center gap-2 rounded-full border border-border bg-card/95 px-3 py-2 shadow-lg backdrop-blur"><span className="h-1.5 w-1.5 rounded-full bg-accent" /><span className="font-mono text-[9px] text-muted-foreground">checkpoint ready</span><input data-testid="input-checkpoint-label" value={checkpointLabel} onChange={(event) => setCheckpointLabel(event.target.value)} placeholder="label snapshot" className="w-24 bg-transparent font-mono text-[9px] text-foreground outline-none placeholder:text-muted-foreground/55" /><button data-testid="button-create-checkpoint" onClick={create} disabled={!checkpointLabel.trim() || createCheckpoint.isPending} className="text-primary disabled:opacity-40">{createCheckpoint.isPending ? <Loader2 size={13} className="animate-spin" /> : <Plus size={13} />}</button></div>
      </div>
    </div>
  );
}

function MessageBubble({ message, index }: { message: ChatMessage; index: number }) {
  const isUser = message.role === 'user';
  return <div className={cn('animate-rise flex gap-3', isUser && 'flex-row-reverse')} style={{ animationDelay: `${Math.min(index * 60, 300)}ms` }}><div className={cn('mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-md border', isUser ? 'border-[#38526a] bg-[#1c2b39] text-[#9fc4df]' : 'border-primary/25 bg-primary/10 text-primary')}>{isUser ? <MessageSquare size={13} /> : <Sparkles size={13} />}</div><div className={cn('max-w-[88%] rounded-lg border px-4 py-3 text-[12px] leading-[1.7]', isUser ? 'border-[#38526a] bg-[#192630] text-[#d8e6ed]' : 'border-border bg-card text-foreground/85')}><div className="mb-1.5 flex items-center gap-2 font-mono text-[9px] uppercase tracking-wider text-muted-foreground">{isUser ? 'you' : 'agent'}<span className="text-border">·</span>{isUser ? 'request' : 'ready'}</div><p className="whitespace-pre-wrap">{message.content}</p></div></div>;
}

function FolderTreeIcon() {
  return <History size={14} />;
}

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

