                  value={draft?.path === selectedPath ? draft.value : activeFile?.content ?? ''}
                  onChange={(value) => setDraft({ path: selectedPath, value })}
                  language={activeFile?.language}
                  onSave={saveFile}
                  saving={writeFile.isPending}
                />
              )
            ) : (
              <EmptyState
                icon={<FileCode2 size={26} />}
                title="Inspect before you change"
                body="Select a file from the tree to open its contents here. Keyboard shortcut: ⌘S saves the active file."
