  }
}
`;

export default function Workspace() {
  const queryClient = useQueryClient();
  const [selectedPath, setSelectedPath] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>(starterMessages);
  const [prompt, setPrompt] = useState('');
  const [mode, setMode] = useState<Mode>('build');
  const [command, setCommand] = useState('pnpm test');
  const [commandResult, setCommandResult] = useState<CommandResult | null>(null);
  const [checkpointLabel, setCheckpointLabel] = useState('');
  const [showTerminal, setShowTerminal] = useState(true);
  const [showTree, setShowTree] = useState(true);
  const [draft, setDraft] = useState<{ path: string; value: string } | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const [expandedDirs, setExpandedDirs] = useState<Record<string, boolean>>({});
  const streamContentRef = useRef('');
  const chatScrollRef = useRef<HTMLDivElement | null>(null);

  const tree = useGetWorkspaceTree();
  const status = useGetAgentStatus();
  const checkpoints = useListCheckpoints();
  const writeFile = useWriteWorkspaceFile();
  const runCommand = useRunWorkspaceCommand();
  const createCheckpoint = useCreateCheckpoint();

  const entries = useMemo<WorkspaceEntry[]>(() => {
    const raw = tree.data?.entries ?? [];
    return raw.map((entry: any) => ({
      path: String(entry.path ?? ''),
      kind: entry.kind === 'directory' ? 'directory' : 'file',
      size: Number(entry.size ?? 0),
    }));
  }, [tree.data?.entries]);

  const file = useGetWorkspaceFile(
    { path: selectedPath || 'README.md' },
    {
      query: {
        enabled: Boolean(selectedPath),
        queryKey: getGetWorkspaceFileQueryKey({ path: selectedPath || 'README.md' }),
      },
    },
  );

  const activeFile = file.data;
  const checkpointCount = checkpoints.data?.length ?? 0;
  const modelName = status.data?.model ?? 'Model offline';

  const workspaceStats = useMemo(() => {
    const files = entries.filter((entry) => entry.kind === 'file');
    return {
      files: files.length,
      bytes: files.reduce((sum, entry) => sum + entry.size, 0),
    };
  }, [entries]);

  const treeNodes = useMemo(() => buildFileTree(entries), [entries]);

  const activeContent = draft?.path === selectedPath ? draft.value : activeFile?.content ?? '';
  const hasUnsavedChanges = selectedPath ? activeContent !== (activeFile?.content ?? '') : false;

  useEffect(() => {
    if (!selectedPath) {
      const firstFile = entries.find((entry) => entry.kind === 'file');
      if (firstFile?.path) {
        setSelectedPath(firstFile.path);
        expandPathDirectories(firstFile.path, setExpandedDirs);
      }
    }
  }, [entries, selectedPath]);

  useEffect(() => {
    if (selectedPath) {
      expandPathDirectories(selectedPath, setExpandedDirs);
    }
  }, [selectedPath]);

  useEffect(() => {
    if (selectedPath && activeFile && draft?.path !== selectedPath) {
      setDraft({ path: selectedPath, value: activeFile.content ?? '' });
    }
  }, [selectedPath, activeFile, draft?.path]);

  useEffect(() => {
    const element = chatScrollRef.current;
    if (!element) return;
    element.scrollTop = element.scrollHeight;
  }, [messages, isStreaming]);

  const sendMessage = async () => {
    const message = prompt.trim();
    if (!message || isStreaming) return;

    const nextMessages: ChatMessage[] = [
      ...messages,
      { role: 'user', content: message },
      { role: 'assistant', content: 'Working through the request' },
    ];

    setMessages(nextMessages);
    setPrompt('');
    setIsStreaming(true);
    streamContentRef.current = '';

    try {
      const response = await fetch('/api/agent/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message,
          history: nextMessages.slice(0, -1),
          mode,
          context: selectedPath || null,
        }),
      });

      if (!response.ok || !response.body) {
        throw new Error('The agent endpoint did not return a stream.');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      const applyEvent = (event: StreamEvent) => {
        if (event.type === 'message') {
          const nextContent = event.content ?? '';
          streamContentRef.current = nextContent;
          setMessages((current) =>
            current.map((item, index) => (index === current.length - 1 ? { ...item, content: nextContent } : item)),
          );
          return;
        }

        if (event.type === 'activity') {
          const detail = event.detail ?? event.label ?? 'Agent activity';
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1
                ? {
                    ...item,
                    content: `${detail}\n\n${streamContentRef.current || item.content}`,
                  }
                : item,
            ),
          );
          return;
        }

        if (event.type === 'tool') {
          const detail = event.path ? `${event.tool ?? 'tool'}: ${event.path}` : `${event.tool ?? 'tool'} completed`;
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1
                ? {
                    ...item,
                    content: `${detail}\n\n${streamContentRef.current || item.content}`,
                  }
                : item,
            ),
          );
          return;
        }

        if (event.type === 'error') {
          const errorText = event.message ?? 'The agent returned an error.';
          streamContentRef.current = errorText;
          setMessages((current) =>
            current.map((item, index) => (index === current.length - 1 ? { ...item, content: errorText } : item)),
          );
        }
      };

      const consumeLine = (line: string) => {
        if (!line.startsWith('data: ')) return;
        const payload = line.slice(6).trim();
        if (!payload) return;
        try {
          const event = JSON.parse(payload) as StreamEvent;
          applyEvent(event);
        } catch {
          const errorText = 'Malformed event received from agent stream.';
          streamContentRef.current = errorText;
          setMessages((current) =>
            current.map((item, index) => (index === current.length - 1 ? { ...item, content: errorText } : item)),
          );
        }
      };

      while (true) {
        const { value, done } = await reader.read();
        buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });

        let newlineIndex = buffer.indexOf('\n');
        while (newlineIndex !== -1) {
          const line = buffer.slice(0, newlineIndex).trimEnd();
          buffer = buffer.slice(newlineIndex + 1);
          consumeLine(line);
          newlineIndex = buffer.indexOf('\n');
        }

        if (done) {
          const tail = buffer.trim();
          if (tail) consumeLine(tail);
          break;
        }
      }
    } catch (error) {
      const errorText = error instanceof Error ? error.message : 'Could not reach the agent endpoint.';
      streamContentRef.current = errorText;
      setMessages((current) =>
        current.map((item, index) => (index === current.length - 1 ? { ...item, content: errorText } : item)),
      );
    } finally {
      setIsStreaming(false);
      queryClient.invalidateQueries({ queryKey: getGetWorkspaceTreeQueryKey() });
      queryClient.invalidateQueries({ queryKey: getListCheckpointsQueryKey() });
    }
  };

