          {isOpen ? <FolderOpen size={14} color="#ffcf70" /> : <Folder size={14} color="#ffcf70" />}
          <span className="tree-name">{node.name}</span>
        </button>

        {isOpen && node.children.length > 0 && (
          <div className="tree-indent">
            {node.children.map((child) => (
              <TreeNodeView
                key={child.path}
                node={child}
                selected={selected}
                expandedDirs={expandedDirs}
                onToggleDirectory={onToggleDirectory}
                onSelect={onSelect}
                depth={depth + 1}
              />
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <button
      type="button"
      className={cn('tree-button', isActive && 'active')}
      onClick={() => onSelect(node.path)}
      title={node.path}
    >
      <span style={{ width: 14, display: 'inline-flex', justifyContent: 'center' }}>
        <FileCode2 size={13} color={isActive ? '#ffcf70' : '#8e9bff'} />
      </span>
      <span className="tree-name">{node.name}</span>
      <span className="tree-meta">{formatBytes(node.size)}</span>
    </button>
  );
}

function buildFileTree(entries: WorkspaceEntry[]) {
  const root: TreeNode = {
    name: '',
    path: '',
    kind: 'directory',
    size: 0,
    children: [],
  };

  for (const entry of entries) {
    const normalizedPath = entry.path.replace(/^\/+/, '').replace(/\/+$/, '');
    if (!normalizedPath) continue;

    const parts = normalizedPath.split('/').filter(Boolean);
    let cursor = root;

    for (let index = 0; index < parts.length; index += 1) {
      const part = parts[index];
      const path = parts.slice(0, index + 1).join('/');
      const isLast = index === parts.length - 1;
      const kind: 'file' | 'directory' = isLast ? (entry.kind === 'directory' ? 'directory' : 'file') : 'directory';

      let child = cursor.children.find((item) => item.name === part && item.path === path);
      if (!child) {
        child = {
          name: part,
          path,
          kind,
          size: isLast ? entry.size : 0,
          children: [],
        };
        cursor.children.push(child);
      } else if (isLast) {
        child.kind = kind;
        child.size = entry.size;
      }

      cursor = child;
    }
  }

  const sortNodes = (nodes: TreeNode[]) => {
    nodes.sort((a, b) => {
      if (a.kind !== b.kind) return a.kind === 'directory' ? -1 : 1;
      return a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' });
    });

    for (const node of nodes) {
      if (node.children.length > 0) {
        sortNodes(node.children);
      }
    }
  };

  sortNodes(root.children);
  return root.children;
}

function expandPathDirectories(
  path: string,
  setExpandedDirs: React.Dispatch<React.SetStateAction<Record<string, boolean>>>,
) {
  const parts = path.split('/').filter(Boolean);
  if (parts.length <= 1) return;

  setExpandedDirs((current) => {
    const next = { ...current };
    for (let index = 0; index < parts.length - 1; index += 1) {
      const dirPath = parts.slice(0, index + 1).join('/');
      next[dirPath] = true;
    }
    return next;
  });
}

function inferLanguageFromPath(path: string) {
  const extension = path.split('.').pop()?.toLowerCase() ?? '';
  if (extension === 'ts' || extension === 'tsx') return 'typescript';
  if (extension === 'js' || extension === 'jsx') return 'javascript';
  if (extension === 'json') return 'json';
  if (extension === 'css') return 'css';
  if (extension === 'html') return 'html';
  if (extension === 'md') return 'markdown';
  if (extension === 'yml' || extension === 'yaml') return 'yaml';
  if (extension === 'sh') return 'shell';
  return extension || 'text';
}

function formatBytes(bytes: number) {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}
