  --red: #ff8778;
  --red-soft: rgba(255, 135, 120, 0.14);
  --radius-sm: 10px;
  --radius-md: 14px;
  --radius-lg: 18px;
  --radius-xl: 22px;
  min-height: calc(100dvh - 54px);
  background:
    radial-gradient(circle at top left, rgba(98, 255, 191, 0.065), transparent 32%),
    radial-gradient(circle at top right, rgba(142, 155, 255, 0.085), transparent 34%),
    linear-gradient(180deg, var(--bg-2), var(--bg));
  color: var(--fg);
  position: relative;
  overflow: hidden;
}

.workspace-shell::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 26px 26px;
  mask-image: linear-gradient(180deg, rgba(0,0,0,0.38), transparent 90%);
  pointer-events: none;
}

.workspace-layout {
  position: relative;
  z-index: 1;
  display: grid;
  min-height: calc(100dvh - 54px);
  grid-template-columns: 1fr;
}

@media (min-width: 1280px) {
  .workspace-layout {
    grid-template-columns: minmax(380px, 1.02fr) minmax(520px, 1.35fr);
  }
}

.workspace-left,
.workspace-right {
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 700px;
}

.workspace-left {
  border-right: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(13, 16, 24, 0.72), rgba(10, 12, 18, 0.58));
  backdrop-filter: blur(18px) saturate(150%);
}

.workspace-right {
  background: linear-gradient(180deg, rgba(10, 12, 17, 0.84), rgba(7, 9, 13, 0.9));
  backdrop-filter: blur(18px) saturate(165%);
}

@media (max-width: 1279px) {
  .workspace-left {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--border);
  background: rgba(14, 17, 24, 0.62);
  backdrop-filter: blur(18px) saturate(150%);
}

.identity {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.identity-mark {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  color: var(--blue);
  background: rgba(142, 155, 255, 0.11);
  border: 1px solid rgba(142, 155, 255, 0.16);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
}

.identity-copy {
  min-width: 0;
}

.identity-title {
  font-size: 13px;
  line-height: 1.1;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--fg);
}

.identity-subtitle {
  margin-top: 4px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fg-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 999px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  border: 1px solid var(--border);
  color: var(--fg-2);
  background: rgba(255, 255, 255, 0.04);
  white-space: nowrap;
}

.badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  flex: 0 0 auto;
}

.badge-green {
  color: rgba(98, 255, 191, 0.85);
  border-color: rgba(98, 255, 191, 0.16);
  background: rgba(98, 255, 191, 0.08);
}

.badge-green .badge-dot {
  background: var(--green);
  box-shadow: 0 0 10px rgba(98, 255, 191, 0.55);
}

.badge-amber {
  color: rgba(255, 207, 112, 0.85);
  border-color: rgba(255, 207, 112, 0.18);
  background: rgba(255, 207, 112, 0.08);
}

.badge-amber .badge-dot {
  background: var(--amber);
  box-shadow: 0 0 10px rgba(255, 207, 112, 0.4);
}

.chat-scroll {
  flex: 1;
  overflow: auto;
  padding: 22px 18px;
}

.chat-column {
  width: 100%;
  max-width: 700px;
  margin: 0 auto;
}

.session-rule {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--fg-4);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.session-rule::before,
.session-rule::after {
  content: '';
  height: 1px;
  flex: 1;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.12), transparent);
}

.message-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.message-row {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.message-row.user {
  flex-direction: row-reverse;
}

.message-avatar {
  width: 32px;
  height: 32px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.045);
  color: var(--blue);
}

.message-row.user .message-avatar {
  color: #9fc4df;
  border-color: rgba(79, 126, 165, 0.35);
  background: rgba(34, 52, 69, 0.44);
}

.message-bubble {
  max-width: min(88%, 760px);
  border-radius: 18px;
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(20, 23, 32, 0.82), rgba(13, 16, 24, 0.84));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
  backdrop-filter: blur(14px) saturate(140%);
  overflow: hidden;
}

.message-row.user .message-bubble {
  border-color: rgba(79, 126, 165, 0.28);
  background: linear-gradient(180deg, rgba(25, 38, 48, 0.78), rgba(19, 31, 40, 0.88));
}

.message-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--fg-3);
}

.message-body {
  padding: 8px 14px 14px;
  font-size: 13px;
  line-height: 1.75;
  color: var(--fg-2);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.stream-card {
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(18, 22, 31, 0.85), rgba(12, 15, 23, 0.85));
  border-radius: 16px;
  padding: 12px 14px;
  color: var(--fg-2);
}

.stream-dots {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.stream-dots span {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--blue);
  animation: workspacePulse 1s infinite ease-in-out;
}

.stream-dots span:nth-child(2) {
  animation-delay: 0.14s;
}

.stream-dots span:nth-child(3) {
  animation-delay: 0.28s;
}

@keyframes workspacePulse {
  0%, 100% { opacity: 0.35; transform: translateY(0); }
  50% { opacity: 1; transform: translateY(-2px); }
}

.composer-wrap {
  padding: 16px 18px 18px;
  border-top: 1px solid var(--border);
  background: rgba(11, 14, 20, 0.72);
  backdrop-filter: blur(18px) saturate(160%);
}

.composer {
  width: 100%;
  max-width: 700px;
  margin: 0 auto;
}

.mode-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.mode-pill {
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--fg-3);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.mode-pill:hover {
  background: var(--hover);
  color: var(--fg-2);
}

.mode-pill.active {
  color: var(--blue);
  background: rgba(142, 155, 255, 0.09);
  border-color: rgba(142, 155, 255, 0.16);
}

.mode-model {
  margin-left: auto;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  color: var(--fg-4);
  white-space: nowrap;
}

.composer-card {
  border-radius: 18px;
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(17, 20, 28, 0.92), rgba(13, 16, 24, 0.92));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
  overflow: hidden;
}

.composer-card:focus-within {
  border-color: rgba(142, 155, 255, 0.22);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04), 0 0 0 1px rgba(142,155,255,0.14);
}

.composer-textarea {
  display: block;
  width: 100%;
  min-height: 108px;
  resize: none;
  padding: 16px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--fg);
  font-size: 14px;
  line-height: 1.65;
}

.composer-textarea::placeholder {
  color: var(--fg-4);
}

.composer-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid var(--border);
  padding: 11px 12px;
}

.composer-hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  color: var(--fg-3);
}

.composer-hint-kbd {
  padding: 4px 7px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  color: var(--fg-2);
}

.icon-button,
.run-button,
.save-button,
.tree-toggle,
.checkpoint-button,
.retry-button,
.terminal-toggle,
.tree-button,
.mode-pill {
  border: 0;
  cursor: pointer;
  transition: transform 160ms ease, background 160ms ease, color 160ms ease, opacity 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}

.icon-button:disabled,
.run-button:disabled,
.save-button:disabled,
.checkpoint-button:disabled {
  opacity: 0.42;
  cursor: not-allowed;
  transform: none;
}

.icon-button {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(142, 155, 255, 0.14);
  color: white;
  border: 1px solid rgba(142, 155, 255, 0.16);
}

.icon-button:hover:not(:disabled) {
  transform: translateY(-1px);
  background: rgba(142, 155, 255, 0.20);
}

.right-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 55px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  background: rgba(16, 19, 28, 0.72);
}

.right-topbar-left,
.right-topbar-right {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.tree-toggle {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: transparent;
  color: var(--fg-3);
}

.tree-toggle:hover {
  background: var(--hover);
  color: var(--fg);
}

.tree-toggle.active {
  background: rgba(255,255,255,0.06);
  color: var(--amber);
}

.branch-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 12px;
  border: 1px solid rgba(142, 155, 255, 0.16);
  background: rgba(142, 155, 255, 0.055);
  color: var(--fg-2);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
}

.divider-y {
  width: 1px;
  height: 18px;
  background: var(--border);
  flex: 0 0 auto;
}

.stats {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  color: var(--fg-4);
  white-space: nowrap;
}

.workspace-main {
  display: flex;
  min-height: 0;
  flex: 1;
}

.sidebar {
  width: 230px;
  min-width: 230px;
  border-right: 1px solid var(--border);
  background: rgba(12, 15, 22, 0.66);
  display: flex;
  flex-direction: column;
}

@media (max-width: 720px) {
  .sidebar {
    width: 192px;
    min-width: 192px;
  }
}

.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
}

.sidebar-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fg-3);
}

.sidebar-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 22px;
  padding: 0 7px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  color: var(--fg-2);
}

.sidebar-scroll {
  flex: 1;
  overflow: auto;
  padding: 10px;
}

.tree-root {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tree-node {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tree-button {
  width: 100%;
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 8px;
  text-align: left;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: var(--fg-2);
  padding: 8px 10px;
}

.tree-button:hover {
  background: var(--hover);
  color: var(--fg);
}

.tree-button.active {
  background: rgba(142, 155, 255, 0.08);
  border-color: rgba(142, 155, 255, 0.14);
  color: var(--fg);
}

.tree-indent {
  margin-left: 16px;
}

.tree-name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.tree-meta {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  color: var(--fg-4);
}

.checkpoint-area {
  border-top: 1px solid var(--border);
  padding: 12px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.checkpoint-heading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fg-3);
}

.checkpoint-input-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.mini-input {
  min-width: 0;
  flex: 1;
  height: 34px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  color: var(--fg);
  padding: 0 12px;
  outline: 0;
  font-size: 12px;
}

.mini-input::placeholder {
  color: var(--fg-4);
}

.mini-input:focus {
  border-color: rgba(142, 155, 255, 0.20);
  box-shadow: 0 0 0 1px rgba(142,155,255,0.14);
}

.checkpoint-button {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(98,255,191,0.1);
  color: var(--green);
  border: 1px solid rgba(98,255,191,0.14);
}

.checkpoint-button:hover:not(:disabled) {
  transform: translateY(-1px);
  background: rgba(98,255,191,0.16);
}

.checkpoint-summary {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  color: var(--fg-3);
}

.editor-region {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.editor-toolbar {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: rgba(16, 19, 28, 0.7);
}

.editor-path {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  color: var(--fg);
}

.file-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(98, 255, 191, 0.075);
  border: 1px solid rgba(98, 255, 191, 0.18);
  color: var(--fg-2);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  white-space: nowrap;
}

.save-button {
  height: 30px;
  padding: 0 11px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--fg-2);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.save-button:hover:not(:disabled) {
  color: var(--amber);
  background: rgba(255,255,255,0.055);
  border-color: rgba(255,255,255,0.14);
}

.editor-frame {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: rgba(9, 12, 17, 0.82);
}

.editor-textarea {
  flex: 1;
  width: 100%;
  min-height: 320px;
  border: 0;
  outline: 0;
  resize: none;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.01), transparent),
    rgba(8, 11, 16, 0.92);
  color: #d8e1ee;
  padding: 18px 18px 24px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12.5px;
  line-height: 1.78;
  tab-size: 2;
  white-space: pre;
  overflow: auto;
}

.editor-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid var(--border);
  padding: 10px 14px;
  background: rgba(12, 15, 21, 0.86);
}

.editor-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  color: var(--fg-3);
  white-space: nowrap;
}

.editor-status-dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
}

.editor-status-dot.clean {
  background: var(--green);
  box-shadow: 0 0 10px rgba(98,255,191,0.35);
}

.editor-status-dot.dirty {
  background: var(--amber);
  box-shadow: 0 0 10px rgba(255,207,112,0.35);
}

.terminal-shell {
  border-top: 1px solid var(--border);
  background: rgba(8, 11, 15, 0.72);
}

.terminal-top {
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: rgba(15, 18, 25, 0.76);
}

.terminal-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fg-2);
}

.terminal-state {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px;
}

.terminal-state.ok {
  color: rgba(98,255,191,0.74);
}

.terminal-state.bad {
  color: rgba(255,135,120,0.78);
}

.terminal-toggle {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: transparent;
  color: var(--fg-4);
}

.terminal-toggle:hover {
  background: var(--hover);
  color: var(--fg);
}

.terminal-body {
  padding: 14px;
  background: rgba(7, 9, 13, 0.94);
}

.terminal-input-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.terminal-dollar {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--green);
}

.terminal-input {
  min-width: 0;
  flex: 1;
  height: 36px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: rgba(255,255,255,0.03);
  color: var(--fg);
  padding: 0 12px;
