}

.terminal-output {
  margin-top: 14px;
  max-height: 220px;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.015), transparent),
    rgba(10, 12, 16, 0.95);
  padding: 14px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  line-height: 1.75;
  white-space: pre-wrap;
  color: #adb8c6;
}

.terminal-output-meta {
  display: block;
  margin-top: 10px;
  color: #687380;
}

.empty-block,
.error-block,
.loading-block {
  flex: 1;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.empty-card,
.error-card {
  width: min(520px, 100%);
  text-align: center;
  border-radius: 20px;
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(17, 20, 28, 0.74), rgba(12, 15, 22, 0.84));
  padding: 30px 24px;
}

.empty-icon,
.error-icon {
  width: 54px;
  height: 54px;
  margin: 0 auto 14px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.04);
  color: var(--blue);
}

.empty-title,
.error-title {
  font-size: 16px;
  line-height: 1.2;
  font-weight: 700;
  color: var(--fg);
}

.empty-body,
.error-body {
  margin: 10px auto 0;
  max-width: 48ch;
  font-size: 13px;
  line-height: 1.75;
  color: var(--fg-3);
}

.retry-button {
  margin-top: 16px;
  min-height: 36px;
  padding: 0 14px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.045);
  color: var(--fg);
}

.retry-button:hover {
  background: rgba(255,255,255,0.08);
}

.loading-card {
  width: min(620px, 100%);
  border-radius: 18px;
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(17, 20, 28, 0.74), rgba(12, 15, 22, 0.84));
  padding: 18px;
}

.loading-line {
  height: 12px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(255,255,255,0.04), rgba(255,255,255,0.09), rgba(255,255,255,0.04));
  background-size: 200% 100%;
  animation: workspaceShimmer 1.5s linear infinite;
}

.loading-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

@keyframes workspaceShimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

@keyframes workspaceRise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-rise {
  animation: workspaceRise 220ms ease both;
}

.workspace-shell button,
.workspace-shell input,
.workspace-shell textarea {
  font: inherit;
}

.workspace-shell :focus-visible {
  outline: 2px solid rgba(142, 155, 255, 0.62);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .workspace-shell *,
  .workspace-shell *::before,
  .workspace-shell *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
`;

export default function Workspace() {
  const queryClient = useQueryClient();
  const [selectedPath, setSelectedPath] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>(starterMessages);
  const [prompt, setPrompt] = useState('');
  const [mode, setMode] = useState<Mode>('build');
  const [command, setCommand] = useState('pnpm test');
  const [commandResult, setCommandResult] = useState<CommandResult | null>(null);
  const [checkpointLabel, setCheckpointLabel] = useState('');
  const [showTerminal, setShowTerminal] = useState(true);
  const [showTree, setShowTree] = useState(true);
  const [draft, setDraft] = useState<{ path: string; value: string } | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const [expandedDirs, setExpandedDirs] = useState<Record<string, boolean>>({});
  const streamContentRef = useRef('');
  const chatScrollRef = useRef<HTMLDivElement | null>(null);

  const tree = useGetWorkspaceTree() as { data?: WorkspaceTreeResponse; isLoading: boolean; isError: boolean; refetch: () => void };
  const status = useGetAgentStatus() as { data?: { configured?: boolean; model?: string } };
  const checkpoints = useListCheckpoints() as { data?: unknown[]; isLoading: boolean };
  const writeFile = useWriteWorkspaceFile();
  const runCommand = useRunWorkspaceCommand();
  const createCheckpoint = useCreateCheckpoint();

  const entries = useMemo<WorkspaceEntry[]>(() => {
    const rawEntries = tree.data?.entries ?? [];
    return rawEntries
      .map((entry) => {
        const rawPath = String(entry.path ?? '').replace(/^\/+/, '').replace(/\/+$/, '');
        const rawKind = entry.kind === 'directory' ? 'directory' : 'file';
        const rawSize = Number(entry.size ?? 0);
        return {
          path: rawPath,
          kind: rawKind,
          size: Number.isFinite(rawSize) ? rawSize : 0,
        };
      })
      .filter((entry) => entry.path.length > 0);
  }, [tree.data]);

  const file = useGetWorkspaceFile(
    { path: selectedPath || 'README.md' },
    {
      query: {
        enabled: Boolean(selectedPath),
        queryKey: getGetWorkspaceFileQueryKey({ path: selectedPath || 'README.md' }),
      },
    },
  ) as {
    data?: WorkspaceFileResponse;
    isLoading: boolean;
    isError: boolean;
    refetch: () => void;
  };

  const activeFile = file.data;
  const checkpointCount = checkpoints.data?.length ?? 0;
  const modelName = status.data?.model ?? 'Model offline';

  const workspaceStats = useMemo(() => {
    const files = entries.filter((entry) => entry.kind === 'file');
    return {
      files: files.length,
      bytes: files.reduce((sum, entry) => sum + entry.size, 0),
    };
  }, [entries]);

  const treeNodes = useMemo(() => buildFileTree(entries), [entries]);
  const activeContent = draft?.path === selectedPath ? draft.value : activeFile?.content ?? '';
  const hasUnsavedChanges = selectedPath ? activeContent !== (activeFile?.content ?? '') : false;

  useEffect(() => {
    if (selectedPath) return;
    const firstFile = entries.find((entry) => entry.kind === 'file');
    if (!firstFile?.path) return;
    setSelectedPath(firstFile.path);
    expandPathDirectories(firstFile.path, setExpandedDirs);
  }, [entries, selectedPath]);

  useEffect(() => {
    if (!selectedPath) return;
    expandPathDirectories(selectedPath, setExpandedDirs);
  }, [selectedPath]);

  useEffect(() => {
    if (!selectedPath || !activeFile) return;
    if (draft?.path === selectedPath) return;
    setDraft({ path: selectedPath, value: activeFile.content ?? '' });
  }, [selectedPath, activeFile, draft?.path]);

  useEffect(() => {
    const element = chatScrollRef.current;
    if (!element) return;
    element.scrollTop = element.scrollHeight;
  }, [messages, isStreaming]);

  const sendMessage = async () => {
    const message = prompt.trim();
    if (!message || isStreaming) return;

    const nextMessages: ChatMessage[] = [
      ...messages,
      { role: 'user', content: message },
      { role: 'assistant', content: 'Working through the request' },
    ];

    setMessages(nextMessages);
    setPrompt('');
    setIsStreaming(true);
    streamContentRef.current = '';

    try {
      const response = await fetch('/api/agent/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message,
          history: nextMessages.slice(0, -1),
          mode,
          context: selectedPath || null,
        }),
      });

      if (!response.ok || !response.body) {
        throw new Error('The agent endpoint did not return a stream.');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      const applyEvent = (event: StreamEvent) => {
        if (event.type === 'message') {
          const nextContent = event.content ?? '';
          streamContentRef.current = nextContent;
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1 ? { ...item, content: nextContent } : item,
            ),
          );
          return;
        }

        if (event.type === 'activity') {
          const detail = event.detail ?? event.label ?? 'Agent activity';
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1
                ? {
                    ...item,
                    content: `${detail}\n\n${streamContentRef.current || item.content}`,
                  }
                : item,
            ),
          );
          return;
        }

        if (event.type === 'tool') {
          const detail = event.path ? `${event.tool ?? 'tool'}: ${event.path}` : `${event.tool ?? 'tool'} completed`;
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1
                ? {
                    ...item,
                    content: `${detail}\n\n${streamContentRef.current || item.content}`,
                  }
                : item,
            ),
          );
          return;
        }

        if (event.type === 'error') {
          const errorText = event.message ?? 'The agent returned an error.';
          streamContentRef.current = errorText;
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1 ? { ...item, content: errorText } : item,
            ),
          );
        }
      };

      const consumeLine = (line: string) => {
        if (!line.startsWith('data: ')) return;
        const payload = line.slice(6).trim();
        if (!payload) return;
        try {
          const event = JSON.parse(payload) as StreamEvent;
          applyEvent(event);
        } catch {
          const errorText = 'Malformed event received from agent stream.';
          streamContentRef.current = errorText;
          setMessages((current) =>
            current.map((item, index) =>
              index === current.length - 1 ? { ...item, content: errorText } : item,
            ),
          );
        }
      };

      while (true) {
        const { value, done } = await reader.read();
        buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });

        let newlineIndex = buffer.indexOf('\n');
        while (newlineIndex !== -1) {
          const line = buffer.slice(0, newlineIndex).trimEnd();
          buffer = buffer.slice(newlineIndex + 1);
          consumeLine(line);
          newlineIndex = buffer.indexOf('\n');
        }

        if (done) {
          const tail = buffer.trim();
          if (tail) consumeLine(tail);
          break;
        }
      }
    } catch (error) {
      const errorText = error instanceof Error ? error.message : 'Could not reach the agent endpoint.';
      streamContentRef.current = errorText;
      setMessages((current) =>
        current.map((item, index) =>
          index === current.length - 1 ? { ...item, content: errorText } : item,
        ),
      );
    } finally {
      setIsStreaming(false);
      queryClient.invalidateQueries({ queryKey: getGetWorkspaceTreeQueryKey() });
      queryClient.invalidateQueries({ queryKey: getListCheckpointsQueryKey() });
    }
  };

  const saveFile = () => {
    if (!selectedPath) return;
    const content = draft?.path === selectedPath ? draft.value : activeFile?.content ?? '';

    writeFile.mutate(
      { data: { path: selectedPath, content } },
      {
        onSuccess: (saved: WorkspaceFileResponse) => {
          setDraft({ path: selectedPath, value: saved.content });
          queryClient.setQueryData(getGetWorkspaceFileQueryKey({ path: selectedPath }), saved);
          queryClient.invalidateQueries({ queryKey: getGetWorkspaceTreeQueryKey() });
        },
      },
    );
  };

  const run = () => {
    const value = command.trim();
    if (!value || runCommand.isPending) return;

    runCommand.mutate(
      {
        data: {
          command: value,
          cwd: tree.data?.root ?? '',
          timeoutMs: 120000,
        },
      },
      {
        onSuccess: (result: CommandResult) => {
          setCommandResult(result);
        },
      },
    );
  };

  const create = () => {
    const label = checkpointLabel.trim();
    if (!label || createCheckpoint.isPending) return;

    createCheckpoint.mutate(
      { data: { label } },
      {
        onSuccess: () => {
          setCheckpointLabel('');
          queryClient.invalidateQueries({ queryKey: getListCheckpointsQueryKey() });
        },
      },
    );
  };

  return (
    <div className="workspace-shell">
      <style>{styles}</style>

      <div className="workspace-layout">
        <section className="workspace-left">
          <div className="topbar">
            <div className="identity">
              <div className="identity-mark">
                <Sparkles size={15} />
              </div>
              <div className="identity-copy">
                <div className="identity-title">Direct the workspace</div>
                <div className="identity-subtitle">conversation / {mode}</div>
              </div>
            </div>
            <StatusBadge configured={Boolean(status.data?.configured)} />
          </div>

          <div ref={chatScrollRef} className="chat-scroll">
            <div className="chat-column">
              <div className="session-rule">Session started</div>

              <div className="message-list">
                {messages.map((message, index) => (
                  <MessageBubble key={`${message.role}-${index}`} message={message} index={index} />
                ))}

                {isStreaming && (
                  <div className="stream-card animate-rise">
                    <div className="identity-mark" style={{ width: 32, height: 32, borderRadius: 12 }}>
                      <Sparkles size={14} />
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 12 }}>
                      <span className="stream-dots" aria-hidden="true">
                        <span />
                        <span />
                        <span />
                      </span>
                      <span>thinking through the change</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="composer-wrap">
            <div className="composer">
              <div className="mode-row">
                {(['plan', 'build', 'debug'] as Mode[]).map((value) => (
                  <button
                    key={value}
                    data-testid={`button-mode-${value}`}
                    type="button"
                    onClick={() => setMode(value)}
                    className={cx('mode-pill', mode === value && 'active')}
                  >
                    {value}
                  </button>
                ))}
                <span className="mode-model">{modelName}</span>
              </div>

              <div className="composer-card">
                <textarea
                  data-testid="input-agent-prompt"
                  className="composer-textarea"
                  value={prompt}
                  onChange={(event) => setPrompt(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) {
                      event.preventDefault();
                      void sendMessage();
                    }
                  }}
                  placeholder="Ask the agent to make a change"
                  rows={4}
                />
                <div className="composer-footer">
                  <div className="composer-hint">
                    <span className="composer-hint-kbd">⌘↵</span>
                    <span>to send</span>
                    <span>·</span>
                    <span>Context: {selectedPath || 'workspace'}</span>
                  </div>
                  <button
                    data-testid="button-send-agent"
                    type="button"
                    onClick={() => void sendMessage()}
                    disabled={!prompt.trim() || isStreaming}
                    className="icon-button"
                    aria-label="Send message"
                  >
                    <Send size={14} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        </section>

        <section className="workspace-right">
          <div className="right-topbar">
            <div className="right-topbar-left">
              <button
                data-testid="button-toggle-tree"
                type="button"
                onClick={() => setShowTree((value) => !value)}
                className={cx('tree-toggle', showTree && 'active')}
                aria-label={showTree ? 'Hide file tree' : 'Show file tree'}
              >
                <PanelLeft size={15} />
              </button>
              <span className="divider-y" />
              <span className="branch-chip">
                <GitBranch size={13} color="#72c9a6" />
                <span>main</span>
              </span>
            </div>

            <div className="right-topbar-right">
              <span className="stats">
                <span>{workspaceStats.files} files</span>
                <span>·</span>
                <span>{formatBytes(workspaceStats.bytes)}</span>
              </span>
            </div>
          </div>

          <div className="workspace-main">
            {showTree && (
              <aside className="sidebar">
                <div className="sidebar-header">
                  <div className="sidebar-title">
                    <FolderOpen size={13} />
                    <span>Files</span>
                  </div>
                  <span className="sidebar-count">{entries.length}</span>
                </div>

                <div className="sidebar-scroll">
                  {tree.isLoading ? (
                    <LoadingBlock lines={10} />
                  ) : tree.isError ? (
                    <ErrorBlock onRetry={() => tree.refetch()} />
                  ) : (
                    <FileTree
                      nodes={treeNodes}
                      selected={selectedPath}
                      expandedDirs={expandedDirs}
                      onToggleDirectory={(path) =>
                        setExpandedDirs((current) => ({
                          ...current,
                          [path]: !current[path],
                        }))
                      }
                      onSelect={(path) => {
                        setSelectedPath(path);
                      }}
                    />
                  )}
                </div>

                <div className="checkpoint-area">
                  <div className="checkpoint-heading">
                    <ShieldCheck size={12} color="#72c9a6" />
                    <span>Checkpoints</span>
                  </div>

                  <div className="checkpoint-input-row">
                    <input
                      data-testid="input-checkpoint-label"
                      className="mini-input"
                      value={checkpointLabel}
                      onChange={(event) => setCheckpointLabel(event.target.value)}
                      placeholder="label snapshot"
                    />
                    <button
                      data-testid="button-create-checkpoint"
                      type="button"
                      onClick={create}
                      disabled={!checkpointLabel.trim() || createCheckpoint.isPending}
                      className="checkpoint-button"
                      aria-label="Create checkpoint"
                    >
                      {createCheckpoint.isPending ? <Loader2 size={13} className="animate-spin" /> : <Plus size={13} />}
                    </button>
                  </div>

                  {checkpoints.isLoading ? (
                    <div className="checkpoint-summary">Loading saved snapshots…</div>
                  ) : (
                    <div className="checkpoint-summary">{checkpointCount} saved snapshots</div>
                  )}
                </div>
              </aside>
            )}

            <div className="editor-region">
              <div className="editor-toolbar">
                <FileCode2 size={14} color="#ffcf70" />
                <div className="editor-path">{selectedPath || 'Select a file to inspect'}</div>
                {selectedPath && (
                  <>
                    <span className="file-chip">
                      <span>{activeFile?.language || inferLanguageFromPath(selectedPath)}</span>
                    </span>
                    <button
                      data-testid="button-save-file"
                      type="button"
                      onClick={saveFile}
                      disabled={!selectedPath || writeFile.isPending}
                      className="save-button"
                    >
                      {writeFile.isPending ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
                      <span>Save</span>
                    </button>
                  </>
                )}
              </div>

              {selectedPath ? (
                file.isLoading ? (
                  <LoadingBlock lines={16} />
                ) : file.isError ? (
                  <ErrorBlock onRetry={() => file.refetch()} />
                ) : (
                  <CodeEditor
                    value={activeContent}
                    language={activeFile?.language || inferLanguageFromPath(selectedPath)}
                    saving={writeFile.isPending}
                    dirty={hasUnsavedChanges}
                    onChange={(value) => setDraft({ path: selectedPath, value })}
                    onSave={saveFile}
                  />
                )
              ) : (
                <EmptyState
                  icon={<FileCode2 size={26} />}
                  title="Inspect before you change"
                  body="Select a file from the tree to open its contents here. Keyboard shortcut: ⌘S saves the active file."
                />
              )}

              <div className="terminal-shell">
                <div className="terminal-top">
                  <div className="terminal-label">
                    <TerminalSquare size={13} color="#72c9a6" />
                    <span>Terminal</span>
                    {commandResult && (
                      <span className={cx('terminal-state', commandResult.exitCode === 0 ? 'ok' : 'bad')}>
                        {commandResult.exitCode === 0 ? 'completed' : 'failed'}
                      </span>
                    )}
                  </div>

                  <button
                    data-testid="button-toggle-terminal"
                    type="button"
                    onClick={() => setShowTerminal((value) => !value)}
                    className="terminal-toggle"
                    aria-label={showTerminal ? 'Collapse terminal' : 'Expand terminal'}
                  >
                    {showTerminal ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                  </button>
                </div>

                {showTerminal && (
                  <div className="terminal-body">
                    <div className="terminal-input-row">
                      <span className="terminal-dollar">$</span>
                      <input
                        data-testid="input-terminal-command"
                        className="terminal-input"
                        value={command}
                        onChange={(event) => setCommand(event.target.value)}
                        onKeyDown={(event) => {
                          if (event.key === 'Enter') {
                            event.preventDefault();
                            run();
                          }
                        }}
                      />
                      <button
                        data-testid="button-run-command"
                        type="button"
                        onClick={run}
                        disabled={runCommand.isPending}
                        className="run-button"
                      >
                        {runCommand.isPending ? <Loader2 size={11} className="animate-spin" /> : <Play size={11} />}
                        <span>Run</span>
                      </button>
                    </div>

                    {commandResult && (
                      <pre data-testid="text-terminal-output" className="terminal-output">
                        {commandResult.stdout || commandResult.stderr || `Command exited with code ${commandResult.exitCode}`}
                        <span className="terminal-output-meta">completed in {commandResult.durationMs}ms</span>
                      </pre>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

function StatusBadge({ configured }: { configured: boolean }) {
  return (
    <span className={cx('badge', configured ? 'badge-green' : 'badge-amber')}>
      <span className="badge-dot" />
      <span>{configured ? 'agent online' : 'configure agent'}</span>
    </span>
  );
}

function MessageBubble({ message, index }: { message: ChatMessage; index: number }) {
  const isUser = message.role === 'user';

  return (
    <div
      className={cx('message-row animate-rise', isUser && 'user')}
      style={{ animationDelay: `${Math.min(index * 50, 250)}ms` }}
    >
      <div className="message-avatar">{isUser ? <MessageSquare size={14} /> : <Sparkles size={14} />}</div>
      <div className="message-bubble">
        <div className="message-meta">
          <span>{isUser ? 'you' : 'agent'}</span>
          <span>·</span>
          <span>{isUser ? 'request' : 'ready'}</span>
        </div>
        <div className="message-body">{message.content}</div>
      </div>
    </div>
  );
}

function LoadingBlock({ lines = 8 }: { lines?: number }) {
  return (
    <div className="loading-block">
      <div className="loading-card">
        <div className="loading-stack">
          {Array.from({ length: lines }).map((_, index) => (
            <div
              key={index}
              className="loading-line"
              style={{
                width:
                  index % 6 === 0
                    ? '92%'
                    : index % 6 === 1
                      ? '76%'
                      : index % 6 === 2
                        ? '98%'
