              <div className="card-header">
                <div className="card-title-wrap">
                  <div className="card-title-icon">
                    <Cpu size={15} />
                  </div>
                  <div className="card-title">Agent connection</div>
                </div>
                <StatusBadge configured={Boolean(status?.configured)} />
              </div>

              {agent.isLoading ? (
                <LoadingBlock lines={5} />
              ) : agent.isError ? (
                <ErrorBlock onRetry={() => agent.refetch()} />
              ) : (
                <div className="card-body">
                  <div className="field-grid">
                    <Field
                      label="Model identifier"
                      icon={<Sparkles size={13} />}
                      value={model}
                      onChange={setModel}
                      placeholder="e.g. claude-3-7-sonnet"
                      testId="input-model"
                    />
                    <Field
                      label="Endpoint"
                      icon={<Server size={13} />}
                      value={endpoint}
                      onChange={setEndpoint}
                      placeholder=""
                      testId="input-endpoint"
                    />
                  </div>

                  <div className="connection-row">
                    <div className={status?.configured ? 'connection-state ok' : 'connection-state warn'}>
                      <Radio size={14} />
                      <span>{status?.configured ? 'Connection is responding' : 'Add credentials to enable the agent'}</span>
                    </div>

                    <button data-testid="button-save-settings" type="button" onClick={save} className="save-button">
                      {saved ? <Check size={14} /> : <Save size={14} />}
                      {saved ? 'Saved locally' : 'Save changes'}
                    </button>
                  </div>
                </div>
              )}
            </section>

            <section className="card">
              <div className="card-header">
                <div className="card-title-wrap">
                  <div className="card-title-icon">
                    <MonitorCog size={15} />
                  </div>
                  <div className="card-title">Workspace behavior</div>
                </div>
              </div>

              <div className="card-body compact" style={{ paddingLeft: 0, paddingRight: 0, paddingBottom: 0 }}>
                <div className="divide-list">
                  <ToggleRow
                    icon={<KeyRound size={15} />}
                    title="Ask before risky commands"
                    body="Keep destructive shell actions behind a confirmation."
                    defaultChecked
                  />
                  <ToggleRow
                    icon={<RotateCcw size={15} />}
                    title="Create checkpoints automatically"
                    body="Snapshot before the agent edits more than one file."
                    defaultChecked
                  />
                  <ToggleRow
                    icon={<Save size={15} />}
                    title="Save editor changes on blur"
                    body="Persist manual edits when you move to another file."
