export default function Settings() {
  const agent = useGetAgentStatus() as AgentStatusQuery;
  const [model, setModel] = useState('');
  const [endpoint, setEndpoint] = useState('');
  const [saved, setSaved] = useState(false);

  const status = agent.data;

  useEffect(() => {
    if (!status) return;
    setModel((current) => (current.length > 0 ? current : status.model ?? ''));
    setEndpoint((current) => (current.length > 0 ? current : status.endpoint ?? ''));
  }, [status]);

  const capabilities = useMemo(() => {
    if (status?.capabilities && status.capabilities.length > 0) {
      return status.capabilities;
    }
    return ['workspace read', 'workspace write', 'command execution'];
  }, [status?.capabilities]);

  const save = () => {
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1800);
  };

  return (
    <div className="settings-shell">
      <style>{styles}</style>

      <div className="settings-wrap">
        <div className="hero">
          <div className="hero-copy">
            <div className="hero-kicker">
              <SlidersHorizontal size={13} />
              configuration surface
            </div>
            <h1 className="hero-title">Settings</h1>
            <p className="hero-body">
              Tune the model connection and the way Agent Studio handles your workspace.
            </p>
          </div>

          <Link href="/" data-testid="link-settings-workspace" className="hero-link">
            Return to workspace
            <ExternalLink size={13} />
          </Link>
        </div>

        <div className="layout">
          <div className="stack">
            <section className="panel">
              <div className="panel-header">
                <div className="panel-title-wrap">
                  <div className="panel-title-icon">
                    <Cpu size={14} />
                  </div>
                  <div className="panel-title">Agent connection</div>
                </div>
                <StatusBadge configured={Boolean(status?.configured)} />
              </div>

              {agent.isLoading ? (
                <LoadingBlock lines={5} />
              ) : agent.isError ? (
                <ErrorBlock onRetry={() => agent.refetch()} />
              ) : (
                <div className="panel-body">
                  <div className="fields">
                    <Field
                      label="Model identifier"
                      icon={<Sparkles size={13} />}
                      value={model}
                      onChange={setModel}
                      placeholder="e.g. claude-3-7-sonnet"
                      testId="input-model"
                    />
                    <Field
                      label="Endpoint"
                      icon={<Server size={13} />}
                      value={endpoint}
                      onChange={setEndpoint}
                      placeholder=""
                      testId="input-endpoint"
                    />
                  </div>

                  <div className="connection-row">
                    <div className={status?.configured ? 'connection-copy ok' : 'connection-copy warn'}>
                      <Radio size={14} />
                      <span className="connection-text">
                        {status?.configured ? 'Connection is responding' : 'Add credentials to enable the agent'}
                      </span>
                    </div>

                    <button data-testid="button-save-settings" type="button" onClick={save} className="save-button">
                      {saved ? <Check size={14} /> : <Save size={14} />}
                      {saved ? 'Saved locally' : 'Save changes'}
                    </button>
                  </div>
                </div>
              )}
            </section>

            <section className="panel">
              <div className="panel-header">
                <div className="panel-title-wrap">
                  <div className="panel-title-icon">
                    <MonitorCog size={14} />
                  </div>
                  <div className="panel-title">Workspace behavior</div>
                </div>
              </div>

              <div className="panel-body-tight">
                <div className="rows">
                  <ToggleRow
                    icon={<KeyRound size={15} />}
                    title="Ask before risky commands"
                    body="Keep destructive shell actions behind a confirmation."
                    defaultChecked
                  />
                  <ToggleRow
                    icon={<RotateCcw size={15} />}
                    title="Create checkpoints automatically"
                    body="Snapshot before the agent edits more than one file."
                    defaultChecked
                  />
                  <ToggleRow
                    icon={<Save size={15} />}
                    title="Save editor changes on blur"
                    body="Persist manual edits when you move to another file."
                  />
                </div>
              </div>
            </section>
          </div>

          <aside className="stack">
            <section className="panel">
              <div className="panel-header">
                <div className="panel-title-wrap">
                  <div className="panel-title-icon">
                    <Cpu size={15} />
                  </div>
                  <div className="panel-title">Capabilities</div>
                </div>
              </div>

              <div className="panel-body">
                <div className="capability-grid">
                  {capabilities.map((capability) => (
                    <div key={capability} data-testid={`text-capability-${capability}`} className="capability-chip">
                      <Check size={12} className="capability-check" />
                      <span>{capability}</span>
                    </div>
                  ))}
                </div>
              </div>
            </section>

            <section className="panel note-panel">
              <div className="note-box">
                <div className="note-kicker">Connection note</div>
                <p className="note-body">
                  Agent Studio never hides the working surface. Prompts, file edits, commands, and checkpoints stay in the room so you can steer with confidence.
                </p>
              </div>
            </section>
          </aside>
        </div>
      </div>
    </div>
  );
}

function Field({
  label,
  icon,
  value,
  onChange,
  placeholder,
  testId,
}: {
  label: string;
  icon: ReactNode;
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  testId: string;
}) {
  return (
    <label className="field">
      <span className="field-label">
        {icon}
        {label}
      </span>
      <input
        data-testid={testId}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        placeholder={placeholder}
        className="field-input"
      />
    </label>
  );
}

function ToggleRow({
  icon,
  title,
  body,
  defaultChecked = false,
}: {
  icon: ReactNode;
  title: string;
  body: string;
  defaultChecked?: boolean;
}) {
  const [checked, setChecked] = useState(defaultChecked);

  return (
    <div className="toggle-row">
      <div className="toggle-icon">{icon}</div>
      <div className="toggle-copy">
        <div className="toggle-title">{title}</div>
        <div className="toggle-body">{body}</div>
      </div>
      <button
        data-testid={`button-toggle-${title.toLowerCase().replaceAll(' ', '-')}`}
        type="button"
        onClick={() => setChecked((value) => !value)}
        aria-pressed={checked}
        className={checked ? 'switch on' : 'switch'}
      >
        <span className="switch-thumb" />
      </button>
    </div>
  );
}

function StatusBadge({ configured }: { configured: boolean }) {
  return (
    <span className={configured ? 'status-badge green' : 'status-badge amber'}>
      <span className="status-badge-dot" />
      {configured ? 'configured' : 'needs setup'}
    </span>
  );
}

function LoadingBlock({ lines }: { lines: number }) {
  return (
    <div className="loading-wrap">
      <div className="loading-stack">
        {Array.from({ length: lines }).map((_, index) => (
          <div
            key={index}
            className="loading-line"
            style={{
              width: `${Math.max(42, 100 - index * 7)}%`,
            }}
          />
        ))}
      </div>
    </div>
  );
}

function ErrorBlock({ onRetry }: { onRetry: () => void }) {
  return (
    <div className="error-wrap">
      <div className="error-card">
        <div className="error-title">Could not load this section</div>
        <div className="error-body">The latest agent status could not be retrieved right now.</div>
        <button type="button" onClick={onRetry} className="retry-button">
          Retry
        </button>
      </div>
    </div>
  );
}
